import React, { useState } from "react";
import ComplaintForm from "./components/ComplaintForm";
import ComplaintList from "./components/ComplaintList";

function App() {
  const [refresh, setRefresh] = useState(false);

  const handleComplaintSubmit = () => {
    // Trigger re-render of ComplaintList after a new complaint is added
    setRefresh(!refresh);
  };

  return (
    <div style={{ padding: "20px" }}>
      <h1>Complaint Portal</h1>
      <ComplaintForm onComplaintSubmit={handleComplaintSubmit} />
      {/* Passing refresh as key will re-fetch complaints */}
      <ComplaintList key={refresh} />
    </div>
  );
}

export default App;
